{"items":[{"id":"cap-v2-graph_and_tree-python-repair-02","test_code":"import unittest

from solution import dependency_layers


class DependencyLayersTests(unittest.TestCase):
    def test_empty_starts_produces_no_layers(self):
        graph = {"a": ["b"], "b": []}
        self.assertEqual(dependency_layers(graph, []), [])

    def test_groups_nodes_by_shortest_distance(self):
        graph = {
            "a": ["b", "c"],
            "b": ["d"],
            "c": ["d", "e"],
            "d": ["f"],
            "e": ["f"],
            "f": [],
            "unreachable": [],
        }
        self.assertEqual(
            dependency_layers(graph, ["a"]),
            [["a"], ["b", "c"], ["d", "e"], ["f"]],
        )

    def test_preserves_discovery_order_and_removes_all_duplicates(self):
        graph = {
            "a": ["c", "b", "c"],
            "d": ["b", "e"],
            "c": ["d", "a"],
            "b": ["d", "f", "f"],
            "e": ["f"],
            "f": ["a"],
        }
        self.assertEqual(
            dependency_layers(graph, ["a", "d", "a"]),
            [["a", "d"], ["c", "b", "e"], ["f"]],
        )

    def test_start_node_reached_by_another_start_is_not_repeated(self):
        graph = {
            "left": ["right", "child"],
            "right": ["child", "left"],
            "child": ["child"],
        }
        self.assertEqual(
            dependency_layers(graph, ["left", "right"]),
            [["left", "right"], ["child"]],
        )

    def test_does_not_mutate_inputs(self):
        graph = {"a": ["b", "b"], "b": ["a"]}
        starts = ["a", "a"]
        original_graph = {node: children[:] for node, children in graph.items()}
        original_starts = starts[:]

        dependency_layers(graph, starts)

        self.assertEqual(graph, original_graph)
        self.assertEqual(starts, original_starts)


if __name__ == "__main__":
    unittest.main()
