from solution import distribute_units


class DistributeUnitsTests(unittest.TestCase):
    def test_even_weights_use_lower_indices_for_ties(self):
        result = distribute_units(10, [1, 1, 1])
        self.assertEqual(result, [4, 3, 3])
        self.assertEqual(sum(result), 10)

    def test_unequal_weights_use_largest_fractional_remainder(self):
        result = distribute_units(7, [1, 2, 3])
        self.assertEqual(result, [1, 2, 4])
        self.assertEqual(sum(result), 7)

    def test_zero_total_returns_new_zero_list(self):
        weights = [4, 0, 6]
        result = distribute_units(0, weights)
        self.assertEqual(result, [0, 0, 0])
        self.assertIsNot(result, weights)

    def test_zero_weight_indices_receive_nothing(self):
        self.assertEqual(distribute_units(7, [0, 5, 0]), [0, 7, 0])

    def test_multiple_tied_remainders_are_awarded_by_index(self):
        self.assertEqual(distribute_units(2, [1, 1, 1, 1]), [1, 1, 0, 0])

    def test_large_integers_are_compared_exactly(self):
        large = 10**30
        self.assertEqual(distribute_units(1, [large, large + 1]), [0, 1])

    def test_does_not_mutate_or_alias_weights(self):
        weights = [2, 3, 5]
        original = weights[:]
        result = distribute_units(11, weights)

        self.assertEqual(weights, original)
        self.assertIsNot(result, weights)
        result[0] += 100
        self.assertEqual(weights, original)


if __name__ == "__main__":
    unittest.main()
